pomerium.description:
note: all clients will be created, regardless if they are used.
if the module is not defined and the secret does not exist,
there will a random secret generated.

policydbro.default:
path "database/*" {
  capabilities = ["list"]
}

path "database/creds/readonly-role*" {
  capabilities = ["read"]
}

path "rabbitmq/creds/readonly*" {
  capabilities = ["read"]
}

policydbrw.default:
path "database/*" {
  capabilities = ["list"]
}

path "database/creds/readwrite-role*" {
  capabilities = ["read"]
}

path "rabbitmq/creds/readwrite*" {
  capabilities = ["read"]
}
